import { describe, it, expect } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// WHY THIS EXISTS
// ---------------
// The reseed is a 7,153-line GENERATED artifact, and "the script reproduces it
// byte-for-byte" has a shelf life: generate-v545-metadata-reseed.mjs computes supersession
// from the live migrations tree, so the first future metadata sync that touches one of the
// 13 replayed rows trips assertShape and the file stops regenerating (deliberately - that
// analysis needs a human at that point). After that, nothing would notice a hand-edit.
//
// This guards the artifact instead of the derivation, so it keeps working afterwards. It
// asserts the structural invariants that make the migration safe to run on EVERY database:
// every create guarded, the delete guarded, the replayed updates left unguarded, and the
// counts the generator pinned.

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const PG_DIR = join(REPO_ROOT, 'migrations-pg', 'v5');

// Matched by suffix rather than full name so re-stamping the migration (which is a real
// possibility while v5.50 counterparts are still landing) does not fail the test, while
// deleting or renaming it away still does.
const RESEED_SUFFIX = '__v5.50.x__Reseed_v545_Metadata.pg-only.sql';

function readReseed() {
    const matches = readdirSync(PG_DIR).filter((f) => f.endsWith(RESEED_SUFFIX));
    expect(matches, `exactly one *${RESEED_SUFFIX} must be committed`).toHaveLength(1);
    return readFileSync(join(PG_DIR, matches[0]), 'utf8');
}

/** Bodies of every `DO $mj$ … END $mj$;` block, in file order. */
function blocks(sql) {
    return [...sql.matchAll(/DO \$mj\$\n([\s\S]*?)\nEND \$mj\$;/g)].map((m) => m[1]);
}

describe('v5.45 reseed migration — structural invariants', () => {
    const sql = readReseed();
    const all = blocks(sql);
    const creates = all.filter((b) => /PERFORM __mj\."spCreate/.test(b));
    const updates = all.filter((b) => /PERFORM __mj\."spUpdate/.test(b));
    const deletes = all.filter((b) => /PERFORM __mj\."spDelete/.test(b));

    it('holds the shape the generator pinned', () => {
        expect({ blocks: all.length, creates: creates.length, updates: updates.length, deletes: deletes.length })
            .toEqual({ blocks: 175, creates: 161, updates: 13, deletes: 1 });
    });

    it('guards every create on its own primary key', () => {
        // Without this the migration is not safe on a database that already has the rows
        // (someone ran `mj sync push`, or a future baseline is already whole).
        const unguarded = creates.filter(
            (b) => !/IF EXISTS \(SELECT 1 FROM __mj\."[A-Za-z0-9_]+" WHERE "ID" = '[0-9A-F-]{36}'\) THEN\s*\n\s*RETURN;/.test(b),
        );
        expect(unguarded).toEqual([]);
    });

    it('guards the delete on the row existing', () => {
        expect(deletes[0]).toMatch(/IF EXISTS \(SELECT 1 FROM __mj\."\w+" WHERE "ID" = '[0-9A-F-]{36}'\) THEN/);
    });

    it('leaves the replayed updates unguarded, since they are idempotent by value', () => {
        // An IF EXISTS guard on an update would be a silent no-op on the gapped databases
        // this migration exists to heal, which is the opposite of what it is for.
        expect(updates.filter((b) => b.includes('IF EXISTS'))).toEqual([]);
    });

    it('creates each row exactly once', () => {
        const ids = creates.map((b) => b.match(/WHERE "ID" = '([0-9A-F-]{36})'/)?.[1]);
        expect(ids.filter(Boolean)).toHaveLength(161);
        expect(new Set(ids).size).toBe(161);
    });

    it('declares itself generated, so nobody edits it by hand', () => {
        expect(sql).toContain('GENERATED by scripts/generate-v545-metadata-reseed.mjs');
    });
});
